// Check the query string against the allow-list before any table is read.
const req = $('Data Table API Request').first().json;
const s = $('API Settings').first().json;
const q = req.query || {};
const fail = (status, code, message) => [{ json: { ok: false, status, code, message } }];
const own = (o, k) => o !== null && typeof o === 'object' && Object.prototype.hasOwnProperty.call(o, k);
const short = (v) => String(v).slice(0, 60);

for (const [k, v] of Object.entries(q)) {
  if (typeof v !== 'string') return fail(400, 'invalid_parameter', 'Give "' + short(k) + '" once, as plain text.');
}
const name = String(q.table ?? '').trim();
if (!name) return fail(400, 'missing_table', 'Add ?table=<name> to the URL.');
const tables = s.public_tables;
if (!own(tables, name)) return fail(404, 'table_not_found', 'No public table named "' + short(name) + '".');
const cfg = tables[name] || {};
const columns = Array.isArray(cfg.columns) ? cfg.columns.map(String) : [];
const where = own(cfg, 'where') && cfg.where && typeof cfg.where === 'object' && !Array.isArray(cfg.where) ? cfg.where : {};
if (typeof cfg.data_table !== 'string' || !cfg.data_table.trim() || !columns.length) {
  return fail(500, 'config_error', 'The API settings for "' + short(name) + '" need data_table and columns.');
}

const whole = (raw) => (/^\d{1,9}$/.test(raw) ? Number(raw) : NaN);
const maxLimit = Math.max(1, Math.floor(Number(s.max_limit)) || 100);
let limit = Math.min(Math.max(1, Math.floor(Number(s.default_limit)) || 20), maxLimit);
if (q.limit !== undefined) {
  limit = whole(q.limit);
  if (!Number.isFinite(limit) || limit < 1) return fail(400, 'invalid_limit', 'limit must be a whole number from 1 to ' + maxLimit + '.');
  limit = Math.min(limit, maxLimit);
}
let offset = 0;
if (q.offset !== undefined) {
  offset = whole(q.offset);
  if (!Number.isFinite(offset)) return fail(400, 'invalid_offset', 'offset must be a whole number of 0 or more.');
}
const sortRaw = q.sort !== undefined ? q.sort.trim() : String(cfg.default_sort ?? '').trim();
let sort = null;
if (sortRaw) {
  const column = sortRaw.replace(/^-/, '');
  if (!columns.includes(column)) return fail(400, 'invalid_sort', 'sort must be one of: ' + columns.join(', ') + ' (add - for descending).');
  sort = { column, desc: sortRaw.startsWith('-') };
}
const RESERVED = ['table', 'limit', 'offset', 'sort'];
const filters = {};
for (const [k, v] of Object.entries(q)) {
  if (RESERVED.includes(k)) continue;
  if (!columns.includes(k)) return fail(400, 'unknown_parameter', 'Unknown parameter "' + short(k) + '". Filter on: ' + columns.join(', ') + '.');
  if (v.trim() === '') return fail(400, 'invalid_filter', 'Filter "' + short(k) + '" needs a value.');
  filters[k] = v;
}
return [{ json: {
  ok: true, public_name: name, data_table: cfg.data_table.trim(), columns, where, limit, offset, sort,
  sort_param: q.sort !== undefined ? q.sort.trim() : '', filters,
} }];

// Use the table whose name matches exactly (the list can contain similar names),
// check that the configured columns exist and that each filter value fits its column type.
// A failed list also sends an empty item here (Always Output Data): stop, the error branch answers.
if ($('Find Data Tables').all(1).length) return [];
const r = $('Check Request').first().json;
const fail = (status, code, message) => [{ json: { ok: false, status, code, message } }];
const own = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
const table = $input.all().map((i) => i.json).find((t) => t && t.id !== undefined && t.name === r.data_table);
if (!table) return fail(500, 'config_error', 'The API settings for "' + r.public_name + '" point to a Data Table that does not exist: ' + r.data_table + '.');
const types = { id: 'number', createdAt: 'date', updatedAt: 'date' };
for (const c of table.columns || []) types[c.name] = c.type;
const needed = [...r.columns, ...Object.keys(r.where)];
const missing = needed.filter((c) => !own(types, c));
if (missing.length) return fail(500, 'config_error', 'The API settings for "' + r.public_name + '" name columns the table does not have: ' + missing.join(', ') + '.');
const filters = {};
for (const [col, raw] of Object.entries(r.filters)) {
  const type = types[col];
  if (type === 'number') {
    if (!/^-?\d+(\.\d+)?$/.test(raw.trim())) return fail(400, 'invalid_filter', 'Filter "' + col + '" must be a number.');
    filters[col] = Number(raw);
  } else if (type === 'boolean') {
    if (raw !== 'true' && raw !== 'false') return fail(400, 'invalid_filter', 'Filter "' + col + '" must be true or false.');
    filters[col] = raw === 'true';
  } else if (type === 'string') {
    filters[col] = raw;
  } else {
    return fail(400, 'invalid_filter', 'Filtering on "' + col + '" (' + type + ') is not supported. Sort on it instead.');
  }
}
return [{ json: { ok: true, table_id: table.id, types, filters } }];

// Keep rows that match the fixed where and the query filters, sort them, cut out one page
// and return only the allowed columns.
// A failed read also sends an empty item here (Always Output Data): stop, the error branch answers.
if ($('Load Rows').all(1).length) return [];
const r = $('Check Request').first().json;
const m = $('Match Table Exactly').first().json;
const s = $('API Settings').first().json;
const types = m.types;
const rows = $input.all().map((i) => i.json).filter((x) => x && x.id !== undefined);
const isEmpty = (v) => v === null || v === undefined || v === '';
const time = (v) => new Date(v).getTime();
const asBool = (v) => v === true || v === 1 || v === 'true' || v === '1';
const same = (cell, want, type) => {
  if (isEmpty(cell)) return isEmpty(want);
  if (type === 'number') return Number(cell) === Number(want);
  if (type === 'boolean') return asBool(cell) === asBool(want);
  if (type === 'date') return time(cell) === time(want);
  return String(cell) === String(want);
};
const conditions = [...Object.entries(r.where), ...Object.entries(m.filters)];
const matched = rows.filter((row) => conditions.every(([col, want]) => same(row[col], want, types[col])));
const compare = (a, b, type) => {
  if (type === 'number') return Number(a) - Number(b);
  if (type === 'date') return time(a) - time(b);
  if (type === 'boolean') return Number(asBool(a)) - Number(asBool(b));
  return String(a).localeCompare(String(b), 'en');
};
matched.sort((a, b) => {
  if (r.sort) {
    const col = r.sort.column; const ea = isEmpty(a[col]); const eb = isEmpty(b[col]);
    if (ea !== eb) return ea ? 1 : -1;
    if (!ea) { const d = compare(a[col], b[col], types[col]); if (d) return r.sort.desc ? -d : d; }
  }
  return a.id - b.id;
});
const pick = (row) => Object.fromEntries(r.columns.map((c) => {
  const v = row[c];
  return [c, v instanceof Date ? v.toISOString() : (v === undefined ? null : v)];
}));
const total = matched.length;
const items = matched.slice(r.offset, r.offset + r.limit).map(pick);
const hasMore = r.offset + items.length < total;
let next = null;
if (hasMore) {
  const p = { table: r.public_name, limit: r.limit, offset: r.offset + r.limit };
  if (r.sort_param) p.sort = r.sort_param;
  Object.assign(p, r.filters);
  const query = Object.entries(p).map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v))).join('&');
  next = String($('Data Table API Request').first().json.webhookUrl).split('?')[0] + '?' + query;
}
const seconds = Math.max(0, Math.floor(Number(s.cache_seconds)) || 0);
const cache = seconds ? 'public, max-age=' + seconds : 'no-store';
return [{ json: { cache_control: cache, body: { table: r.public_name, total, limit: r.limit, offset: r.offset, count: items.length, hasMore, next, items } } }];
